#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct EdgeMux { payload: u64 }

impl EdgeMux {
    pub const ID: u32 = CAN_ID_EDGEMUX;
    pub const DLC: u8 = CAN_DLC_EDGEMUX;
    pub const fn new() -> Self { Self { payload: 0 } }
    pub const fn from_payload(payload: u64) -> Self { Self { payload } }
    pub const fn payload(&self) -> u64 { self.payload }
    pub fn set_payload(&mut self, payload: u64) { self.payload = payload; }
    pub const fn frame(&self) -> CanFrame {
        CanFrame { id: Self::ID, dlc: Self::DLC, payload: self.payload }
    }

    pub fn get_mux(&self) -> Result<u8, DbccError> {
        let raw = dbcc_extract(self.payload, 0u32, 8u32, false);
        let value = raw as u8;
        if (value as f64) < 0_f64 || (value as f64) > 255_f64 {
            return Err(DbccError::OutOfRange { signal: "mux" });
        }
        Ok(value)
    }

    pub fn set_mux(&mut self, value: u8) -> Result<(), DbccError> {
        if (value as f64) < 0_f64 || (value as f64) > 255_f64 {
            return Err(DbccError::OutOfRange { signal: "mux" });
        }
        let raw = value as u64;
        dbcc_insert(&mut self.payload, 0u32, 8u32, false, raw);
        Ok(())
    }

    pub fn get_muxed_a(&self) -> Result<u8, DbccError> {
        let mux = dbcc_extract(self.payload, 0u32, 8u32, false);
        if !((mux >= 1u64 && mux <= 1u64)) {
            return Err(DbccError::InactiveMultiplexedSignal { signal: "muxed_a", mux });
        }
        let raw = dbcc_extract(self.payload, 8u32, 8u32, false);
        let value = raw as u8;
        if (value as f64) < 0_f64 || (value as f64) > 255_f64 {
            return Err(DbccError::OutOfRange { signal: "muxed_a" });
        }
        Ok(value)
    }

    pub fn set_muxed_a(&mut self, value: u8) -> Result<(), DbccError> {
        let mux = dbcc_extract(self.payload, 0u32, 8u32, false);
        if !((mux >= 1u64 && mux <= 1u64)) {
            return Err(DbccError::InactiveMultiplexedSignal { signal: "muxed_a", mux });
        }
        if (value as f64) < 0_f64 || (value as f64) > 255_f64 {
            return Err(DbccError::OutOfRange { signal: "muxed_a" });
        }
        let raw = value as u64;
        dbcc_insert(&mut self.payload, 8u32, 8u32, false, raw);
        Ok(())
    }

    pub fn get_muxed_b(&self) -> Result<u8, DbccError> {
        let mux = dbcc_extract(self.payload, 0u32, 8u32, false);
        if !((mux >= 2u64 && mux <= 2u64)) {
            return Err(DbccError::InactiveMultiplexedSignal { signal: "muxed_b", mux });
        }
        let raw = dbcc_extract(self.payload, 8u32, 8u32, false);
        let value = raw as u8;
        if (value as f64) < 0_f64 || (value as f64) > 255_f64 {
            return Err(DbccError::OutOfRange { signal: "muxed_b" });
        }
        Ok(value)
    }

    pub fn set_muxed_b(&mut self, value: u8) -> Result<(), DbccError> {
        let mux = dbcc_extract(self.payload, 0u32, 8u32, false);
        if !((mux >= 2u64 && mux <= 2u64)) {
            return Err(DbccError::InactiveMultiplexedSignal { signal: "muxed_b", mux });
        }
        if (value as f64) < 0_f64 || (value as f64) > 255_f64 {
            return Err(DbccError::OutOfRange { signal: "muxed_b" });
        }
        let raw = value as u64;
        dbcc_insert(&mut self.payload, 8u32, 8u32, false, raw);
        Ok(())
    }

}

